    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers

def _load(v):
    if isinstance(v, (dict, list)):
        return v
    if not isinstance(v, str) or not v.strip():
        return {}
    t = v.strip()
    try:
        return json.loads(t)
    except Exception:
        try:
            if ':' in t and not t.startswith('{'):
                return json.loads(t.split(':', 1)[1].strip())
        except Exception:
            pass
        return {}
async def main(args):
    p = args.params
    req_id = str(p.get('req_id') or '')
    template = str(p.get('template') or '')
    raw_results = p.get('results')
    if not isinstance(raw_results, list):
        raw_results = [raw_results] if raw_results else []
    offers = []
    for i, item in enumerate(raw_results, start=1):
        obj = _load(item)
        if isinstance(obj, list):
            for sub in obj:
                if isinstance(sub, dict):
                    sub.setdefault('offer_seq', len(offers) + 1)
                    offers.append(sub)
            continue
        if isinstance(obj, dict):
            if isinstance(obj.get('offers'), list):
                for sub in obj['offers']:
                    if isinstance(sub, dict):
                        sub.setdefault('offer_seq', len(offers) + 1)
                        offers.append(sub)
            elif obj:
                obj.setdefault('offer_seq', i)
                offers.append(obj)
    for idx, o in enumerate(offers, start=1):
        o.setdefault('offer_seq', idx)
        o.setdefault('template', template)
    # V3.14：按权威名册（需求提报 offers，含 name/quantity）合并销售品名称与数量，
    # 使执行方案 offers[] 从环节2 起即携带 name/quantity，供全链路文案一致（名册缺失时零变化）。
    offers = _merge_roster(offers, p.get('record_json') or p.get('roster') or '')
    ret: Output = {'result_json': json.dumps({'req_id': req_id, 'template': template, 'offers': offers}, ensure_ascii=False)}
    return ret

